from pathlib import Path
import json,base64,hashlib,sys
root=Path(__file__).resolve().parents[1];game=sys.argv[1];out=Path.cwd();files=['store.js','app.js','index.html','sw.js','README.md']+[str(p.relative_to(root)) for p in (root/'store'/game).iterdir() if p.is_file()]+[str(p.relative_to(root)) for p in (root/'tools').iterdir() if p.is_file()]+[str(p.relative_to(root)) for p in (root/'tests').glob(game+'-*') if p.suffix in ['.cjs','.json','.html'] and not p.name.endswith('app-package.html')]+['tests/series-mods.cjs','tests/series-mods-results.json','tests/arcade-mods.cjs','tests/boost-cache.cjs','tests/stick-cache.cjs','tests/knockout-cache.cjs'];files=list(dict.fromkeys(files));manifest=[]
for i,rel in enumerate(files):
 data=(root/rel).read_bytes();enc='base64' if rel.endswith(('.png','.jpg','.mp3')) else 'utf-8';s=base64.b64encode(data).decode() if enc=='base64' else data.decode();transport=str(out/(game+'-upload-'+str(i)+'.txt'));Path(transport).write_text(s);sha=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest();reuse=rel.endswith('/three.min.js') or rel.endswith('/THREE-LICENSE.txt');manifest.append({'path':rel,'transport':transport,'encoding':enc,'chars':len(s),'sha':sha,'reuse':reuse})
p=out/(game+'-upload-manifest.json');p.write_text(json.dumps(manifest));print(json.dumps({'manifest':str(p),'files':len(files),'bytes':sum((root/x).stat().st_size for x in files)}))
